    await setupMcp();
    const initial = await screenshot("screen-initial.png");
    let input = initialBrowserActionInput({
      headless: protocol.browserLaunchOptions.headless,
      scenario: config.scenario,
      parameters,
      initialURL: config.initialURL,
      imageUrl: initial.image_url,
      caseInstruction: caseEvidence.instruction,
    });
    let previous;
    let advertisedEvidence = new Map();
    const executionStatusTool = createExecutionStatusTool();
