              await executeSettledActions(
                [action],
                (value) => execute(value, number, item.call_id),
                () =>
                  settleComputerAction(navigationGuard.wait, () => {
                    checkNavigation();
                    if (!nativeTransition?.events.length) boundPage();
                  }),
              );
