        boundPage(capturePage);
        const snapshot = await capturePage.locator("body").ariaSnapshot();
        boundPage(capturePage);
        const observation = { url: capturePage.url(), text, snapshot };
        await save("terminal-ui.original.json", observation);
        boundPage(capturePage);
        await save("terminal-ui.json", projectRunnerUi(observation, redact));
        boundPage(capturePage);
        const bytes = await capturePage.screenshot();
        boundPage(capturePage);
        await save("terminal.png", bytes);
        await caseEvidence.screenshot("terminal.png", sha256(bytes));
